// Palm Shores — textures.js
// One job: procedural canvas textures — lit windows, asphalt, neon signs, water.
// No image files anywhere: every visual in the game is generated by this module.
function makeCanvas(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  return c;
}

export function buildingTexture(rng, hue) {
  const c = makeCanvas(128, 256, (g, w, h) => {
    g.fillStyle = `hsl(${hue}, 22%, ${10 + rng.range(0, 8)}%)`;
    g.fillRect(0, 0, w, h);
    for (let y = 10; y < h - 12; y += 18) {
      for (let x = 10; x < w - 12; x += 18) {
        const lit = rng.chance(0.55);
        g.fillStyle = lit ? rng.pick(['#ffd166', '#9be7ff', '#ff9de2', '#fff3b0']) : '#0b1020';
        g.globalAlpha = lit ? rng.range(0.55, 1) : 1;
        g.fillRect(x, y, 11, 12);
      }
    }
    g.globalAlpha = 1;
  });
  return c;
}

export function roadTexture() {
  const c = makeCanvas(128, 128, (g, w, h) => {
    g.fillStyle = '#16181f'; g.fillRect(0, 0, w, h);
    g.fillStyle = '#1d2029';
    for (let i = 0; i < 260; i++) g.fillRect(Math.random() * w, Math.random() * h, 2, 2);
    // centre dashes, wet sheen streaks
    g.fillStyle = '#d8c25a'; g.fillRect(w / 2 - 2, 6, 4, 26); g.fillRect(w / 2 - 2, 70, 4, 26);
    g.fillStyle = 'rgba(120,160,255,0.10)'; g.fillRect(8, 0, 10, h); g.fillRect(w - 22, 0, 8, h);
  });
  return c;
}

export function neonSignTexture(text, color) {
  const c = makeCanvas(256, 64, (g, w, h) => {
    g.fillStyle = '#05060a'; g.fillRect(0, 0, w, h);
    g.font = 'bold 34px Arial, sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.shadowColor = color; g.shadowBlur = 18;
    g.strokeStyle = color; g.lineWidth = 2;
    g.strokeText(text, w / 2, h / 2 + 1);
    g.fillStyle = '#ffffff';
    g.shadowBlur = 10;
    g.fillText(text, w / 2, h / 2 + 1);
  });
  return c;
}

export function waterTexture() {
  const c = makeCanvas(128, 128, (g, w, h) => {
    g.fillStyle = '#06121f'; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 40; i++) {
      g.strokeStyle = `rgba(80,180,255,${0.08 + Math.random() * 0.16})`;
      g.lineWidth = 1 + Math.random() * 2;
      const y = Math.random() * h;
      g.beginPath(); g.moveTo(Math.random() * w, y); g.lineTo(Math.random() * w + 30, y); g.stroke();
    }
  });
  return c;
}

export function sidewalkTexture() {
  const c = makeCanvas(64, 64, (g, w, h) => {
    g.fillStyle = '#23262e'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#171a20'; g.lineWidth = 2;
    g.strokeRect(1, 1, w - 2, h - 2);
    g.fillStyle = '#2b2f3a';
    for (let i = 0; i < 24; i++) g.fillRect(Math.random() * w, Math.random() * h, 2, 2);
  });
  return c;
}
